WITH filtered_inventory AS (SELECT * FROM inventory WHERE store_id = 6 AND last_restock > '2023-04-01'), inventory_stats AS (SELECT store_id, CASE WHEN quantity >= 199 THEN 'high' WHEN quantity >= 107 THEN 'mid' ELSE 'low' END AS quantity_bucket, MAX(quantity) - MIN(quantity) AS quantity_range FROM filtered_inventory GROUP BY store_id, CASE WHEN quantity >= 199 THEN 'high' WHEN quantity >= 107 THEN 'mid' ELSE 'low' END) SELECT store_id, quantity_bucket, quantity_range FROM inventory_stats WHERE quantity_range >= 52 ORDER BY quantity_bucket
